/* Generated by Trae Work */
/* 历年真题合计页：考研 408 分年（2009—2026）+ 自考真题列表 */
"use strict";
(function () {
  document.addEventListener("DOMContentLoaded", () => {
    const KY = SITE_DATA.kaoyan;
    const ZK = SITE_DATA.zikao;

    /* ---------- 考研 408：分年试卷 + 答案 ---------- */
    const box408 = document.getElementById("ky-408-years");
    const py = KY.papers.find(p => p.paper_years);
    if (py && py.paper_years) {
      const y0 = py.paper_years.start, y1 = py.paper_years.end;
      const rows = [];
      for (let y = y0; y <= y1; y++) {
        const paper = py.paper_years.paper_pattern.replace("{y}", y);
        const answer = py.paper_years.answer_pattern.replace("{y}", y);
        rows.push(`<tr>
          <td class="yr">${y}</td>
          <td><a href="${paper}" target="_blank" rel="noopener">试卷 PDF（papers-rebuild/${y}.pdf）</a></td>
          <td><a href="${answer}" target="_blank" rel="noopener">答案 PDF（answers/${y}-answer.pdf）</a></td>
        </tr>`);
      }
      box408.innerHTML = `
        <h3>${py.title}</h3>
        <p class="muted">来源平台：${py.source_platform} · 来源类型：${py.source_type === "original" ? "原始试卷（仓库中转）" : py.source_type} · 收录快照：${py.crawled_at}</p>
        <table class="paper-table">
          <thead><tr><th>年份</th><th>试卷</th><th>答案</th></tr></thead>
          <tbody>${rows.join("")}</tbody>
        </table>
        <p class="src" style="margin-top:10px;">完整 URL：${py.paper_years.paper_pattern}<br>${py.paper_years.answer_pattern}</p>
        <p class="src">仓库总览：<a href="${py.source_url}" target="_blank" rel="noopener">${py.source_url}</a></p>
        <p style="font-size:13.5px;">${py.note}</p>`;
    } else {
      box408.innerHTML = `<div class="notice empty">暂无已收录 408 分年真题。</div>`;
    }

    /* ---------- 自考真题列表（按课程分组） ---------- */
    const list = document.getElementById("zk-papers-list");
    const count = document.getElementById("zk-paper-count");
    count.textContent = ZK.papers.length;
    const groups = {};
    ZK.papers.forEach(p => { (groups[p.course_code] = groups[p.course_code] || []).push(p); });
    const order = Object.keys(groups).sort();
    if (!order.length) {
      list.innerHTML = `<div class="notice empty"><strong>暂无已收录真题。</strong>${ZK.papers_empty_note || ""}</div>`;
    } else {
      list.innerHTML = order.map(code => {
        const c = SITE_DATA.zikao.courses.find(x => x.code === code);
        const name = c ? c.name : "";
        const old = c && c.old_code ? `（旧代码 ${c.old_code}）` : "";
        const items = groups[code].map(p => `
          <div class="card paper-card">
            <div class="p-title">${p.title}</div>
            <p class="muted">来源平台：${p.source_platform} · 来源类型：原始试卷 · 收录快照：${p.crawled_at}</p>
            <p style="font-size:13.5px;margin-top:4px;">${p.note}</p>
            <p class="src" style="margin-top:6px;">来源：<a href="${p.source_url}" target="_blank" rel="noopener">${p.source_url}</a></p>
          </div>`).join("");
        return `<h3 style="margin-top:18px;">${code} ${name}${old} <span class="badge zikao">${groups[code].length} 套</span></h3>${items}`;
      }).join("");
    }
    const note = document.getElementById("zk-papers-note");
    if (note && ZK.papers_note) note.textContent = ZK.papers_note;

    /* ---------- 爬虫收录目录（exam100 计算机类自考真题） ---------- */
    const CAT = window.PAPER_CATALOG;
    if (CAT && CAT.courses) {
      document.getElementById("cat-total").textContent = CAT.courses.reduce((n, c) => n + c.count, 0);
      document.getElementById("cat-courses").textContent = CAT.courses.length;
      document.getElementById("cat-meta").textContent =
        `${CAT.meta.source_platform} · ${CAT.meta.crawl_scope} · 抓取并逐条验证 ${CAT.meta.crawl_date}（全部 HTTP 200）。仅收录标题与链接，标题逐字取自来源页面；标注“本专业相关”的为 080901 计划内课程（含旧代码卷，仅作参考来源）。`;
      const box = document.getElementById("paper-catalog");
      /* 本地镜像索引：code|year|month → dir/files */
      const LOC = window.PAPERS_LOCAL || {};
      const localGet = (code, y, m) => (LOC[code] || []).find(x => x.year === y && x.month === m);
      /* 本专业相关课程排前 */
      const ordered = [...CAT.courses].sort((a, b) => (b.my_plan - a.my_plan) || (b.count - a.count));
      box.innerHTML = ordered.map(c => {
        const tag = c.my_plan ? ` <span class="badge ok">本专业相关${c.old_of ? "（旧代码 " + c.old_of + "）" : ""}</span>` : "";
        const rows = c.papers.map(p => {
          const loc = localGet(c.code, p.year, p.month);
          const localBadge = loc
            ? ` <a class="badge ok" style="text-decoration:none;" href="paper-viewer.html?code=${c.code}&y=${p.year}&m=${p.month}">离线查看 · ${loc.pages} 页</a>`
            : "";
          return `<li>${p.year} 年 ${p.month} 月 · ${p.province}${p.has_answer ? " · 含答案" : ""} — <a href="${p.url}" target="_blank" rel="noopener">${p.title}</a>${localBadge}</li>`;
        }).join("");
        return `<details class="chapters"${c.my_plan ? " open" : ""}><summary>${c.code}《${c.course}》· ${c.count} 套${tag}</summary><ul class="chapter-list">${rows}</ul></details>`;
      }).join("");
    }

    /* ---------- 导航高亮由 common.js 处理；本页无额外交互 ---------- */
  });
})();
